package com.client.multichatwindows.config.ui; import com.client.multichatwindows.config.ConfigManager; import net.minecraft.client.*; import net.minecraft.client.gui.*; import net.minecraft.client.gui.screen.Screen; import net.minecraft.text.Text; import java.util.*; public class ServersScreen extends ScrollableDarkScreen { private final Screen parent; private int scrollY=0; public ServersScreen(Screen parent){super(Text.translatable("multichatwindows.servers.title"));this.parent=parent;} @Override protected void init(){clearChildren();int cx=width/2,top=54,bottom=height-90,rowH=24;List<String> servers=ConfigManager.listServers();int max=Math.max(0,servers.size()*rowH-(bottom-top));scrollY=Math.max(0,Math.min(scrollY,max));int y=top-scrollY;for(String key:servers){if(y+20>=top&&y<=bottom){addDrawableChild(new DarkButton(cx-100,y,160,20,Text.translatable("multichatwindows.server.button",Text.literal(key)),()->MinecraftClient.getInstance().setScreen(new TabsScreen(this,key))));addDrawableChild(new DarkButton(cx+64,y,36,20,Text.translatable("multichatwindows.delete"),()->{ConfigManager.deleteServer(key);init();}));}y+=rowH;}addDrawableChild(new DarkButton(cx-100,height-54,200,20,Text.translatable("multichatwindows.servers.add"),()->MinecraftClient.getInstance().setScreen(new AddServerScreen(this))));addDrawableChild(new DarkButton(cx-100,height-28,200,20,Text.translatable("multichatwindows.back"),()->MinecraftClient.getInstance().setScreen(parent)));} @Override protected boolean onScroll(int delta){scrollY+=delta;init();return true;} @Override public void render(DrawContext ctx,int mouseX,int mouseY,float delta){super.render(ctx,mouseX,mouseY,delta);ctx.drawCenteredTextWithShadow(textRenderer,Text.translatable("multichatwindows.servers.title"),width/2,14,0xFFFFFFFF);} }
